var continuation: AsyncStream<Frame>.Continuation!
let stream = AsyncStream<Frame>(bufferingPolicy: .bufferingNewest(64)) {
    continuation = $0
}

producer.onFrame { frame in
    if case .dropped(let old) = continuation.yield(frame) {
        metrics.recordDrop(old)                 // loss is visible, not silent
    }
}
for await frame in stream { process(frame) }    // pull: waits when empty

publisher
    .flatMap(maxPublishers: .max(8)) { request in
        URLSession.shared.dataTaskPublisher(for: request)   // at most 8 in flight
    }
    .sink(receiveValue: render)

